"use client"

import * as React from "react"
import { useAppliedFilter } from "@querycn/filter-react"
import {
  enTableMessages,
  type DataTableInstance,
  type TableMessages,
} from "@querycn/table-react"

import { cn } from "@/lib/utils"
import { TableHead, TableHeader, TableRow } from "@/registry/radix/ui/table"
import {
  headerCellClassName,
  pinnedCellClassName,
} from "@/registry/shared/table/data-table-cell-classes"
import {
  getHeaderCellProps,
  getPinnedEdges,
} from "@/registry/shared/table/data-table-pinning"
import {
  canReorderColumns,
  ColumnReorder,
} from "@/registry/shared/table/column-reorder"
import { useTableContainer } from "@/registry/shared/table/column-layout-actions"
import { useScrollEdges } from "@/registry/shared/table/use-scroll-edges"
import { useScrollToTopOnChange } from "@/registry/shared/table/use-scroll-to-top-on-change"
import { useVirtualRows } from "@/registry/shared/table/use-virtual-rows"
import {
  DataTableBody,
  type DataTableBodyOptions,
} from "@/registry/radix/table/data-table-body"
import { DataTableColumnHeader } from "@/registry/radix/table/data-table-column-header"

export interface DataTableProps<TData extends object>
  extends
    Omit<React.ComponentProps<"div">, "children">,
    DataTableBodyOptions<TData> {
  table: DataTableInstance<TData>
  messages?: TableMessages
  /**
   * Renders only the rows in view, for long pages (thousands of rows). Needs
   * a height on the table, e.g. `className="h-[600px]"`. Fitting a column to
   * its content then measures the rendered rows only.
   */
  virtualize?: boolean
  /** A row's height before it's measured, in pixels. */
  estimateRowHeight?: number
}

/**
 * Renders a `useDataTable` table: sticky header, pinned columns, loading,
 * empty and error states. The container scrolls, so give it a height (e.g.
 * `className="max-h-[600px]"`) for the header to stay in view. Scrolls back
 * to the top when the sort, page, search or filter changes.
 */
export function DataTable<TData extends object>({
  table,
  messages = enTableMessages,
  virtualize = false,
  estimateRowHeight = 37,
  isLoading,
  isError,
  onRetry,
  onRowClick,
  onRowDoubleClick,
  rowClassName,
  emptyState,
  errorState,
  skeletonRows,
  className,
  ...props
}: DataTableProps<TData>) {
  const [scrollRef, scrolled] = useScrollEdges<HTMLDivElement>()
  useTableContainer(table, scrollRef)
  const columns = [
    ...table.getStartVisibleLeafColumns(),
    ...table.getCenterVisibleLeafColumns(),
    ...table.getEndVisibleLeafColumns(),
  ]
  const edges = getPinnedEdges(table)
  const headerGroups = table.getHeaderGroups()
  const canReorder = canReorderColumns(table)
  const rows = table.getRowModel().rows
  const rowCount = rows.length
  const { sorting, pagination } = table.store.state
  const { queryKey } = useAppliedFilter()
  useScrollToTopOnChange(
    scrollRef,
    JSON.stringify([sorting, pagination, queryKey, table.options.meta?.search])
  )
  const virtual = useVirtualRows({
    enabled: virtualize && !isError,
    count: rowCount,
    getRowId: React.useCallback((index: number) => rows[index]!.id, [rows]),
    scrollRef,
    estimateRowHeight,
  })

  return (
    <div
      ref={scrollRef}
      data-slot="data-table"
      data-scroll-start={scrolled.start || undefined}
      data-scroll-end={scrolled.end || undefined}
      className={cn(
        "group/data-table relative w-full overflow-auto rounded-md border",
        className
      )}
      {...props}
    >
      <ColumnReorder table={table} messages={messages}>
        <table
          data-slot="table"
          aria-busy={isLoading || undefined}
          // Screen readers count every row, not only those rendered.
          aria-rowcount={
            virtual && rowCount > 0 ? headerGroups.length + rowCount : undefined
          }
          className="table-fixed caption-bottom text-sm"
          style={{ width: table.getTotalSize() }}
        >
          <TableHeader className="sticky top-0 z-20 bg-background">
            {headerGroups.map((headerGroup) => (
              <TableRow key={headerGroup.id} className="hover:bg-transparent">
                {headerGroup.headers.map((header) =>
                  header.subHeaders.length === 0 ? (
                    <DataTableColumnHeader
                      key={header.id}
                      table={table}
                      header={header}
                      edges={edges}
                      messages={messages}
                      canReorder={canReorder}
                    />
                  ) : (
                    <TableHead
                      key={header.id}
                      colSpan={header.colSpan}
                      {...getHeaderCellProps(header, edges)}
                      className={cn(pinnedCellClassName, headerCellClassName)}
                    >
                      {header.isPlaceholder ? null : (
                        <div className="truncate">
                          <table.FlexRender header={header} />
                        </div>
                      )}
                    </TableHead>
                  )
                )}
              </TableRow>
            ))}
          </TableHeader>
          <DataTableBody
            table={table}
            columns={columns}
            edges={edges}
            messages={messages}
            virtual={virtual}
            headerRowCount={headerGroups.length}
            isLoading={isLoading}
            isError={isError}
            onRetry={onRetry}
            onRowClick={onRowClick}
            onRowDoubleClick={onRowDoubleClick}
            rowClassName={rowClassName}
            emptyState={emptyState}
            errorState={errorState}
            skeletonRows={skeletonRows}
          />
        </table>
      </ColumnReorder>
    </div>
  )
}

"use client"

import * as React from "react"
import {
  createDataTableColumnHelper,
  enTableMessages,
  type DataTableColumnDef,
  type TableMessages,
} from "@querycn/table-react"

import { Checkbox } from "@/registry/radix/ui/checkbox"

// shadcn's checkbox draws "some selected" with its check icon; show a dash instead.
const MIXED =
  "aria-[checked=mixed]:border-primary aria-[checked=mixed]:bg-primary aria-[checked=mixed]:text-primary-foreground aria-[checked=mixed]:before:h-0.5 aria-[checked=mixed]:before:w-2 aria-[checked=mixed]:before:rounded-full aria-[checked=mixed]:before:bg-current aria-[checked=mixed]:[&_svg]:hidden"

/**
 * A checkbox column for row selection: the header one selects the page.
 * Pinned to the start and can't be hidden, sorted or resized.
 */
export function createSelectionColumn<TData extends object>(
  messages: Pick<TableMessages, "selection"> = enTableMessages
): DataTableColumnDef<TData> {
  return createDataTableColumnHelper<TData>().display({
    id: "select",
    size: 40,
    enableSorting: false,
    enableHiding: false,
    enablePinning: false,
    enableResizing: false,
    meta: { defaultPinned: "start", enableOrdering: false },
    header: ({ table }) => (
      <Checkbox
        aria-label={messages.selection.selectAll}
        className={MIXED}
        checked={
          table.getIsAllPageRowsSelected() ||
          (table.getIsSomePageRowsSelected() && "indeterminate")
        }
        onCheckedChange={(checked) =>
          table.toggleAllPageRowsSelected(!!checked)
        }
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        aria-label={messages.selection.selectRow}
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(checked) => row.toggleSelected(!!checked)}
      />
    ),
  })
}

"use client"

import * as React from "react"
import type {
  DataTableInstance,
  DataTableRow,
  TableMessages,
} from "@querycn/table-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import { Skeleton } from "@/registry/radix/ui/skeleton"
import { TableBody, TableCell, TableRow } from "@/registry/radix/ui/table"
import { pinnedCellClassName } from "@/registry/shared/table/data-table-cell-classes"
import { useColumnDragCell } from "@/registry/shared/table/column-reorder"
import {
  getColumnCellProps,
  type getPinnedEdges,
} from "@/registry/shared/table/data-table-pinning"
import {
  isFromControl,
  isRowClick,
} from "@/registry/shared/table/data-table-row-clicks"
import type { VirtualRows } from "@/registry/shared/table/use-virtual-rows"

export interface DataTableBodyOptions<TData extends object> {
  /** Skeleton rows on the first load; dims the rows while they reload. */
  isLoading?: boolean
  isError?: boolean
  onRetry?: () => void
  onRowClick?: (row: DataTableRow<TData>, event: React.MouseEvent) => void
  onRowDoubleClick?: (row: DataTableRow<TData>, event: React.MouseEvent) => void
  rowClassName?: (row: DataTableRow<TData>) => string | undefined
  emptyState?: React.ReactNode
  errorState?: React.ReactNode
  skeletonRows?: number
}

type Column<TData extends object> = ReturnType<
  DataTableInstance<TData>["getAllLeafColumns"]
>[number]

/** The rows of a `DataTable`, or its loading, empty or error state. */
export function DataTableBody<TData extends object>({
  table,
  columns,
  edges,
  messages,
  virtual,
  headerRowCount,
  isLoading = false,
  isError = false,
  onRetry,
  onRowClick,
  onRowDoubleClick,
  rowClassName,
  emptyState,
  errorState,
  skeletonRows = 5,
}: DataTableBodyOptions<TData> & {
  table: DataTableInstance<TData>
  /** Visible leaf columns, in the order shown. */
  columns: Column<TData>[]
  edges: ReturnType<typeof getPinnedEdges>
  messages: TableMessages
  virtual: VirtualRows | null
  headerRowCount: number
}) {
  const rows = table.getRowModel().rows
  const dragCell = useColumnDragCell()

  let body: React.ReactNode
  if (isError) {
    body = (
      <StateRow colSpan={columns.length}>
        {errorState ?? (
          <div className="flex flex-col items-center gap-2">
            <p>{messages.states.error}</p>
            {onRetry && (
              <Button variant="outline" size="sm" onClick={onRetry}>
                {messages.actions.retry}
              </Button>
            )}
          </div>
        )}
      </StateRow>
    )
  } else if (isLoading && rows.length === 0) {
    body = Array.from({ length: skeletonRows }, (_, index) => (
      <TableRow key={index} className="group/row hover:bg-transparent">
        {columns.map((column) => (
          <TableCell
            key={column.id}
            {...getColumnCellProps(column, edges)}
            className={pinnedCellClassName}
          >
            <Skeleton className="h-4 w-full" />
          </TableCell>
        ))}
      </TableRow>
    ))
  } else if (rows.length === 0) {
    body = (
      <StateRow colSpan={columns.length}>
        {emptyState ?? messages.states.empty}
      </StateRow>
    )
  } else {
    const shown = virtual
      ? virtual.items.map((item) => ({
          row: rows[item.index]!,
          index: item.index,
        }))
      : rows.map((row, index) => ({ row, index }))
    body = shown.map(({ row, index }) => (
      <TableRow
        key={row.id}
        ref={virtual?.measureRow}
        data-index={index}
        aria-rowindex={virtual ? headerRowCount + index + 1 : undefined}
        data-state={row.getIsSelected() ? "selected" : undefined}
        onClick={
          onRowClick &&
          ((event) => {
            if (isRowClick(event)) onRowClick(row, event)
          })
        }
        onDoubleClick={
          onRowDoubleClick &&
          ((event) => {
            if (!isFromControl(event)) onRowDoubleClick(row, event)
          })
        }
        className={cn(
          "group/row",
          onRowClick && "cursor-pointer",
          rowClassName?.(row)
        )}
      >
        {[
          ...row.getStartVisibleCells(),
          ...row.getCenterVisibleCells(),
          ...row.getEndVisibleCells(),
        ].map((cell) => (
          <TableCell
            key={cell.id}
            {...dragCell(
              cell.column.id,
              getColumnCellProps(cell.column, edges)
            )}
            className={pinnedCellClassName}
          >
            <div className="truncate">
              <table.FlexRender cell={cell} />
            </div>
          </TableCell>
        ))}
      </TableRow>
    ))
  }

  return (
    <TableBody
      className={cn(
        "transition-opacity",
        isLoading && rows.length > 0 && "pointer-events-none opacity-60"
      )}
    >
      {virtual && (
        <SpacerRow height={virtual.before} colSpan={columns.length} />
      )}
      {body}
      {virtual && <SpacerRow height={virtual.after} colSpan={columns.length} />}
    </TableBody>
  )
}

function StateRow({
  colSpan,
  children,
}: {
  colSpan: number
  children: React.ReactNode
}) {
  return (
    <TableRow className="hover:bg-transparent">
      <TableCell
        colSpan={colSpan}
        className="h-24 text-center text-muted-foreground"
      >
        {children}
      </TableCell>
    </TableRow>
  )
}

// Stands in for the rows scrolled out of view.
function SpacerRow({ height, colSpan }: { height: number; colSpan: number }) {
  if (height <= 0) return null
  return (
    <tr aria-hidden>
      <td colSpan={colSpan} className="p-0" style={{ height }} />
    </tr>
  )
}

"use client"

import * as React from "react"
import type { DataTableInstance, TableMessages } from "@querycn/table-react"
import {
  ArrowDownIcon,
  ArrowUpIcon,
  ChevronsUpDownIcon,
  GripVerticalIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { TableHead } from "@/registry/radix/ui/table"
import {
  headerCellClassName,
  pinnedCellClassName,
} from "@/registry/shared/table/data-table-cell-classes"
import {
  getHeaderCellProps,
  type PinnedEdges,
} from "@/registry/shared/table/data-table-pinning"
import { getColumnLabel } from "@/registry/shared/table/column-label"
import { hasColumnMenu } from "@/registry/shared/table/column-layout-actions"
import { DataTableColumnMenu } from "@/registry/radix/table/data-table-column-menu"
import { ColumnGuideLine } from "@/registry/shared/table/column-guide-line"
import { useColumnDrag } from "@/registry/shared/table/column-reorder"
import { ColumnResizeHandle } from "@/registry/shared/table/column-resize-handle"
import { useColumnColorPicker } from "@/registry/shared/table/use-column-color-picker"

type Header<TData extends object> = ReturnType<
  DataTableInstance<TData>["getFlatHeaders"]
>[number]

const ARIA_SORT = { asc: "ascending", desc: "descending" } as const

/**
 * A leaf column's header cell: click to sort (Shift+click adds the column to
 * the sort), drag it to reorder, drag the end edge to resize. Its ⋯ button, or
 * a right-click, opens a menu to sort, pin, fit, color or hide the column.
 */
export function DataTableColumnHeader<TData extends object>({
  table,
  header,
  edges,
  messages,
  canReorder,
}: {
  table: DataTableInstance<TData>
  header: Header<TData>
  edges: PinnedEdges
  messages: TableMessages
  canReorder: boolean
}) {
  const { column } = header
  const label = getColumnLabel(column)
  const sorted = column.getIsSorted()
  const sortIndex =
    sorted && table.store.state.sorting.length > 1
      ? column.getSortIndex() + 1
      : undefined
  const {
    disabled: isFixed,
    isDragging,
    dropSide,
    setNodeRef,
    pointerProps,
    setHandleRef,
    handleProps,
    style: dragStyle,
  } = useColumnDrag(column, canReorder)
  const cellProps = getHeaderCellProps(header, edges)
  const [menuOpen, setMenuOpen] = React.useState(false)
  const colorPicker = useColumnColorPicker()
  const hasMenu = hasColumnMenu(column)
  const SortIcon =
    sorted === "asc"
      ? ArrowUpIcon
      : sorted === "desc"
        ? ArrowDownIcon
        : ChevronsUpDownIcon

  const title = (
    <>
      <span className="truncate">
        <table.FlexRender header={header} />
      </span>
      {column.columnDef.meta?.required && (
        <span aria-hidden className="text-destructive">
          *
        </span>
      )}
    </>
  )

  return (
    <TableHead
      ref={setNodeRef}
      colSpan={header.colSpan}
      aria-sort={
        column.getCanSort() ? (sorted ? ARIA_SORT[sorted] : "none") : undefined
      }
      data-dragging={isDragging || undefined}
      onContextMenu={(event) => {
        if (!hasMenu) return
        event.preventDefault()
        setMenuOpen(true)
      }}
      {...cellProps}
      style={{ ...cellProps.style, ...dragStyle }}
      className={cn(
        pinnedCellClassName,
        headerCellClassName,
        "group/header data-dragging:z-30"
      )}
    >
      <div
        {...pointerProps}
        className={cn(
          "flex min-w-0 items-center",
          !isFixed && "cursor-grab active:cursor-grabbing"
        )}
      >
        {column.getCanSort() ? (
          <button
            type="button"
            onClick={column.getToggleSortingHandler()}
            className="-mx-1 flex min-w-0 items-center gap-1 rounded-sm px-1 py-0.5 outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            {title}
            <SortIcon
              aria-hidden
              className={cn(
                "size-3.5 shrink-0",
                !sorted &&
                  "text-muted-foreground opacity-0 group-hover/header:opacity-100"
              )}
            />
            {sortIndex !== undefined && (
              <span className="text-xs text-muted-foreground tabular-nums">
                {sortIndex}
              </span>
            )}
          </button>
        ) : (
          <span className="flex min-w-0 items-center gap-1">{title}</span>
        )}
      </div>
      {/* After the content: `measureColumnWidth` measures a cell's first child. */}
      {!isFixed && (
        <button
          type="button"
          ref={setHandleRef}
          aria-label={messages.header.move(label)}
          {...handleProps}
          className="pointer-events-none absolute start-0.5 top-1/2 z-10 flex size-5 -translate-y-1/2 items-center justify-center rounded-sm bg-background text-muted-foreground opacity-0 outline-none focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <GripVerticalIcon className="size-3.5" />
        </button>
      )}
      {hasMenu && (
        <DataTableColumnMenu
          table={table}
          column={column}
          messages={messages}
          open={menuOpen}
          onOpenChange={setMenuOpen}
          onCustomColor={() => colorPicker.open(column)}
          className="absolute end-1.5 top-1/2 z-10 -translate-y-1/2"
        />
      )}
      <input {...colorPicker.inputProps} />
      {dropSide && (
        <ColumnGuideLine
          className={dropSide === "start" ? "-start-px" : "-end-px"}
        />
      )}
      {column.getCanResize() && (
        <ColumnResizeHandle
          header={header}
          label={messages.header.resize(label)}
        />
      )}
    </TableHead>
  )
}

"use client"

import * as React from "react"
import {
  enTableMessages,
  type DataTableInstance,
  type TableMessages,
} from "@querycn/table-react"
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  ChevronsLeftIcon,
  ChevronsRightIcon,
  MoreHorizontalIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/radix/ui/select"
import { getPaginationState } from "@/registry/shared/table/data-table-pagination-state"
import { pageRange } from "@/registry/shared/table/page-range"
import { useKeepFocusInPagination } from "@/registry/shared/table/use-keep-focus-in-pagination"

export interface DataTablePaginationProps<TData extends object> extends Omit<
  React.ComponentProps<"div">,
  "children"
> {
  table: DataTableInstance<TData>
  messages?: TableMessages
  /** Page buttons between the arrows, ellipses included. */
  slots?: number
}

/**
 * Row count, rows per page and page buttons for a `useDataTable` table.
 * Hidden while there are no rows.
 */
export function DataTablePagination<TData extends object>({
  table,
  messages = enTableMessages,
  slots = 7,
  className,
  ...props
}: DataTablePaginationProps<TData>) {
  const state = getPaginationState(table)
  const navProps = useKeepFocusInPagination(state.page)
  if (state.isEmpty) return null
  const { pagination: labels, counts } = messages

  return (
    <div
      data-slot="data-table-pagination"
      className={cn(
        "flex flex-wrap items-center justify-between gap-x-6 gap-y-2 text-sm",
        className
      )}
      {...props}
    >
      <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
        <p className="text-muted-foreground tabular-nums">
          {state.selectedCount > 0
            ? counts.selected(state.selectedCount, state.pageRowCount)
            : state.rowCount !== undefined && counts.rows(state.rowCount)}
        </p>
        {state.showPageSizes && (
          <div className="flex items-center gap-2">
            <span
              aria-hidden
              className="hidden text-muted-foreground sm:inline"
            >
              {labels.rowsPerPage}
            </span>
            <Select
              value={String(state.pageSize)}
              onValueChange={(value) => {
                const pageSize = Number(value)
                if (pageSize > 0 && pageSize !== state.pageSize)
                  table.setPagination({ pageIndex: 0, pageSize })
              }}
            >
              <SelectTrigger
                size="sm"
                aria-label={labels.rowsPerPage}
                className="tabular-nums"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent position="popper" align="end">
                {state.pageSizes.map((size) => (
                  <SelectItem key={size} value={String(size)}>
                    {counts.number(size)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </div>
      {state.showPages && (
        <nav
          {...navProps}
          aria-label={labels.label}
          className="flex items-center gap-3 outline-none"
        >
          {/* From sm up the page buttons show this, and include the first and last page. */}
          <span
            className={cn(
              "font-medium tabular-nums",
              state.pageCount !== undefined && "sm:hidden"
            )}
          >
            {counts.page(state.page, state.pageCount)}
          </span>
          <ul className="flex items-center gap-1">
            {state.pageCount !== undefined && (
              <li className="sm:hidden">
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label={labels.first}
                  disabled={!state.hasPrevious}
                  onClick={() => table.firstPage()}
                >
                  <ChevronsLeftIcon className="rtl:rotate-180" />
                </Button>
              </li>
            )}
            <li>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={labels.previous}
                disabled={!state.hasPrevious}
                onClick={() => table.previousPage()}
              >
                <ChevronLeftIcon className="rtl:rotate-180" />
              </Button>
            </li>
            {state.pageCount !== undefined &&
              pageRange(state.page, state.pageCount, slots).map((item) =>
                typeof item === "number" ? (
                  <li key={item} className="hidden sm:block">
                    <Button
                      variant={item === state.page ? "outline" : "ghost"}
                      size="icon-sm"
                      aria-label={counts.page(item, undefined)}
                      aria-current={item === state.page ? "page" : undefined}
                      onClick={() => table.setPageIndex(item - 1)}
                      className="w-auto min-w-7 px-1.5 tabular-nums"
                    >
                      {counts.number(item)}
                    </Button>
                  </li>
                ) : (
                  <li key={item} className="hidden sm:block">
                    <span className="flex size-7 items-center justify-center text-muted-foreground">
                      <MoreHorizontalIcon aria-hidden className="size-4" />
                      <span className="sr-only">{labels.morePages}</span>
                    </span>
                  </li>
                )
              )}
            <li>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={labels.next}
                disabled={!state.hasNext}
                onClick={() => table.nextPage()}
              >
                <ChevronRightIcon className="rtl:rotate-180" />
              </Button>
            </li>
            {state.pageCount !== undefined && (
              <li className="sm:hidden">
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label={labels.last}
                  disabled={!state.hasNext}
                  onClick={() => table.lastPage()}
                >
                  <ChevronsRightIcon className="rtl:rotate-180" />
                </Button>
              </li>
            )}
          </ul>
        </nav>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import {
  enTableMessages,
  type DataTableInstance,
  type TableMessages,
