  React.ComponentProps<"div">,
  "children"
> {
  table: DataTableInstance<TData>
  messages?: TableMessages
  /** What can be done with the selected rows, e.g. a delete button. */
  actions?: (rows: DataTableRow<TData>[]) => React.ReactNode
}

