  DataTableInstance<TData>["getAllLeafColumns"]
>[number]

const groupOf = (column: { getIsPinned: () => false | Group }): Group =>
  column.getIsPinned() || "center"

/**
 * Users can move columns: `useDataTable`'s `enableColumnOrdering` isn't
 * `false`, and there are no group headers (moving a column out of its group
 * would break the group).
 */
export function canReorderColumns<TData extends object>(
  table: DataTableInstance<TData>
) {
  return (
    table.options.meta?.enableColumnOrdering !== false &&
    table.getHeaderGroups().length === 1
  )
}

/** `meta.enableOrdering: false`, or pinned for good, keeps a column in place. */
function isMovable<TData extends object>(column: Column<TData>) {
  if (column.columnDef.meta?.enableOrdering === false) return false
  return !(column.getIsPinned() && !column.getCanPin())
}

/** Moves `from` to `to`'s place among the movable ids; the others keep theirs. */
function moveAmong(
  ids: string[],
  from: string,
  to: string,
  isMovable: (id: string) => boolean
) {
  const movable = ids.filter(isMovable)
  const moved = arrayMove(movable, movable.indexOf(from), movable.indexOf(to))
  let next = 0
  return ids.map((id) => (isMovable(id) ? moved[next++]! : id))
}

// Pinned columns move within their pinned group only.
const sameGroup: CollisionDetection = (args) =>
  closestCenter({
    ...args,
    droppableContainers: args.droppableContainers.filter(
      (container) =>
        container.data.current?.movable &&
        container.data.current.group === args.active.data.current?.group
    ),
  })

type Axis = "x" | "y"

const alongAxis: Record<Axis, Modifier> = {
  x: ({ transform }) => ({ ...transform, y: 0 }),
  y: ({ transform }) => ({ ...transform, x: 0 }),
}

const AxisContext = React.createContext<Axis>("x")

// In a table the other columns stay put: the moved one's cells follow the
// pointer (by this variable, set on the table's container) and a line marks
// where it will land. Only a list makes room as an item moves.
const DRAG_X = "--data-table-drag-x"

interface TableDrag {
  activeId: string
  /** The column it will land next to, on that column's start or end side. */
  target: { id: string; side: "start" | "end" } | null
}

function getTableDrag(
  ids: string[],
  drag: { active: string; over: string | null } | null
): TableDrag | null {
  if (!drag) return null
  const { active, over } = drag
  const from = ids.indexOf(active)
  const to = over === null ? -1 : ids.indexOf(over)
  return {
    activeId: active,
    // Moved right it lands after the column it's over, moved left before it.
    target:
      over === null || to === -1 || over === active
        ? null
        : { id: over, side: from < to ? "end" : "start" },
  }
}

const TableDragContext = React.createContext<TableDrag | null>(null)

// A sensor keeps listening on the document until the drag ends, even once its
// DndContext unmounts (a popover closing mid-drag); the next Enter would drop.
// These report themselves so `ColumnReorder` can stop them when it unmounts.
interface Detachable {
  detach: () => void
}
interface Tracked {
  onAttach?: (sensor: Detachable) => void
}

class TrackedKeyboardSensor extends KeyboardSensor {
  constructor(props: KeyboardSensorProps) {
    super(props)
    ;(props.options as Tracked).onAttach?.(this as unknown as Detachable)
  }
}

class TrackedPointerSensor extends PointerSensor {
  constructor(props: PointerSensorProps) {
    super(props)
    ;(props.options as Tracked).onAttach?.(this as unknown as Detachable)
  }
}

/**
 * Lets header cells be dragged (by `useColumnDrag`'s handle) to reorder
 * columns: the column order for unpinned columns, the pinned order for pinned
 * ones. Wrap the table in it, or with `axis="y"` a list of every column,
 * hidden ones included.
 */
export function ColumnReorder<TData extends object>({
  table,
  messages,
  axis = "x",
  onDraggingChange,
  children,
}: {
  table: DataTableInstance<TData>
  messages: TableMessages
  axis?: Axis
  /** E.g. to keep a popover around the list open while a column moves. */
  onDraggingChange?: (dragging: boolean) => void
  children: React.ReactNode
}) {
  // Stable ids for the screen reader descriptions, so server and client HTML match.
  const id = React.useId()
  const sensor = React.useRef<Detachable | null>(null)
  const onAttach = React.useCallback((attached: Detachable) => {
    sensor.current = attached
  }, [])
  React.useEffect(() => () => sensor.current?.detach(), [])
  const sensors = useSensors(
    useSensor(TrackedPointerSensor, {
      activationConstraint: { distance: 4 },
      onAttach,
    } as PointerSensorOptions & Tracked),
    useSensor(TrackedKeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
      onAttach,
    } as KeyboardSensorOptions & Tracked)
  )
  const columns =
    axis === "y"
      ? getListedColumns(table)
      : [
          ...table.getStartVisibleLeafColumns(),
          ...table.getCenterVisibleLeafColumns(),
          ...table.getEndVisibleLeafColumns(),
        ]
  // While dragging, only the columns that can trade places with it make room.
  const [activeGroup, setActiveGroup] = React.useState<Group | null>(null)
  const [dragIds, setDragIds] = React.useState<{
    active: string
    over: string | null
  } | null>(null)
  const items = columns
    .filter(
      (column) =>
        isMovable(column) && (!activeGroup || groupOf(column) === activeGroup)
    )
    .map((column) => column.id)
  const tableDrag = axis === "x" ? getTableDrag(items, dragIds) : null

  const describe = (id: UniqueIdentifier) => {
    const column = table.getColumn(String(id))
    if (!column) return { label: String(id), position: 0, total: 0 }
    const group = columns.filter((c) => groupOf(c) === groupOf(column))
    return {
      label: getColumnLabel(column),
      position: group.findIndex((c) => c.id === column.id) + 1,
      total: group.length,
    }
  }
  const announcements: Announcements = {
    onDragStart: ({ active }) =>
      messages.header.pickedUp(describe(active.id).label),
    onDragOver: ({ active, over }) => {
      if (!over) return
      const { position, total } = describe(over.id)
      return messages.header.movedTo(describe(active.id).label, position, total)
    },
    onDragEnd: ({ active, over }) => {
      if (!over) return messages.header.cancelled(describe(active.id).label)
      const { position, total } = describe(over.id)
      return messages.header.dropped(describe(active.id).label, position, total)
    },
    onDragCancel: ({ active }) =>
      messages.header.cancelled(describe(active.id).label),
  }

  const onDragEnd = ({ active, over }: DragEndEvent) => {
    setActiveGroup(null)
    setDragIds(null)
    onDraggingChange?.(false)
    const from = table.getColumn(String(active.id))
    const to = over && table.getColumn(String(over.id))
    if (!from || !to || from.id === to.id) return
    const group = groupOf(from)
    if (group !== groupOf(to)) return
    const canMove = (id: string) => {
      const column = table.getColumn(id)
      return column !== undefined && isMovable(column)
    }
    const move = (ids: string[]) => moveAmong(ids, from.id, to.id, canMove)
    if (group === "center") table.setColumnOrder((order) => move(order))
    else {
      table.setColumnPinning((pinning) => ({
        ...pinning,
        [group]: move(pinning[group]),
      }))
    }
  }

  return (
    <DndContext
      id={id}
      sensors={sensors}
      collisionDetection={sameGroup}
      modifiers={[alongAxis[axis]]}
      accessibility={{
        announcements,
        screenReaderInstructions: { draggable: messages.header.instructions },
      }}
      onDragStart={({ active }) => {
        setActiveGroup(active.data.current?.group ?? null)
        setDragIds({ active: String(active.id), over: null })
        onDraggingChange?.(true)
      }}
      onDragOver={({ active, over }) =>
        setDragIds({
          active: String(active.id),
          over: over ? String(over.id) : null,
        })
      }
      onDragCancel={() => {
        setActiveGroup(null)
        setDragIds(null)
        onDraggingChange?.(false)
      }}
      onDragEnd={onDragEnd}
    >
      <SortableContext
        items={items}
        strategy={
          axis === "y"
            ? verticalListSortingStrategy
            : horizontalListSortingStrategy
        }
      >
        <AxisContext value={axis}>
          <TableDragContext value={tableDrag}>{children}</TableDragContext>
        </AxisContext>
      </SortableContext>
    </DndContext>
  )
}

/** A header cell's or list item's part in `ColumnReorder`: its node, drag handles and offset while moving. */
export function useColumnDrag<TData extends object>(
  column: Column<TData>,
  canReorder: boolean
) {
  const axis = React.use(AxisContext)
  const group = groupOf(column)
  const enabled = canReorder && isMovable(column)
  const { active } = useDndContext()
  // Keyboard moves pick the next droppable column, so other groups step aside too.
  const otherGroup = active !== null && active.data.current?.group !== group
  const {
    node,
    setNodeRef,
    setActivatorNodeRef,
    attributes,
    listeners,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: column.id,
    disabled: { draggable: !enabled, droppable: !enabled || otherGroup },
    data: { group, movable: enabled },
  })
  const tableDrag = React.use(TableDragContext)
  const inTable = axis === "x"
  const x = inTable && isDragging && transform ? Math.round(transform.x) : 0
  React.useLayoutEffect(() => {
    if (!x) return
    const container = node.current?.closest<HTMLElement>(
      "[data-slot=data-table]"
    )
    container?.style.setProperty(DRAG_X, `${x}px`)
    return () => {
      container?.style.removeProperty(DRAG_X)
    }
  }, [node, x])
  return {
    disabled: !enabled,
    setNodeRef,
    // The pointer drags the header itself (a click without moving still sorts);
    // the keyboard picks the column up from a handle.
    pointerProps: {
      onPointerDown: listeners?.onPointerDown as
        React.PointerEventHandler | undefined,
    },
    setHandleRef: setActivatorNodeRef,
    handleProps: {
      ...attributes,
      onKeyDown: listeners?.onKeyDown as React.KeyboardEventHandler | undefined,
    },
    isDragging,
    /** In a table, the side of this column the moved one will land on. */
    dropSide:
      tableDrag?.target?.id === column.id ? tableDrag.target.side : undefined,
    style: (inTable
      ? { transform: x ? `translate3d(${x}px, 0, 0)` : undefined }
      : {
          transform: transform
            ? `translate3d(0, ${Math.round(transform.y)}px, 0)`
            : undefined,
          transition,
        }) satisfies React.CSSProperties,
  }
}

/** A body cell's part in `ColumnReorder`: adds to its props so it follows its column's header while that moves. */
export function useColumnDragCell() {
  const tableDrag = React.use(TableDragContext)
  return <TProps extends { style?: React.CSSProperties }>(
    columnId: string,
    props: TProps
  ) =>
    tableDrag?.activeId === columnId
      ? {
          ...props,
          "data-dragging": true,
          style: {
            ...props.style,
            transform: `translate3d(var(${DRAG_X}, 0px), 0, 0)`,
          },
        }
      : props
}

"use client"

import * as React from "react"
import type { DataTableInstance } from "@querycn/table-react"

import { cn } from "@/lib/utils"
import { ColumnGuideLine } from "@/registry/shared/table/column-guide-line"
import {
  getColumnWidthBounds,
  measureColumnWidths,
} from "@/registry/shared/table/column-layout-actions"

type Header<TData extends object> = ReturnType<
  DataTableInstance<TData>["getFlatHeaders"]
>[number]

const STEP = 10
const LARGE_STEP = 50

/**
 * The drag handle on a header's end edge: drag to resize, double-click to fit
 * the content, or focus it and use ←/→ (Shift for bigger steps).
 */
export function ColumnResizeHandle<TData extends object>({
  header,
  label,
}: {
  header: Header<TData>
  label: string
}) {
  const { column } = header
  const table = header.getContext().table
  const { min, max } = getColumnWidthBounds(column)
  const isResizing = column.getIsResizing()
  // TanStack flips the offset in right-to-left tables; the line follows the pointer.
  const direction = table.options.columnResizeDirection === "rtl" ? -1 : 1
  const size = column.getSize()
  const delta = isResizing
    ? (table.store.state.columnResizing.deltaOffset ?? 0)
    : 0
  // Where the edge will land: the committed width stays within min and max.
  const preview =
    (Math.min(Math.max(size + delta, min), max) - size) * direction

  const setWidth = (width: number) =>
    table.setColumnSizing((sizes) => ({
      ...sizes,
      [column.id]: Math.min(Math.max(Math.round(width), min), max),
    }))

  const onResize = header.getResizeHandler()
  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label={label}
      aria-valuenow={size}
      aria-valuemin={min}
      aria-valuemax={max}
      tabIndex={0}
      data-slot="data-table-resize-handle"
      data-resizing={isResizing || undefined}
      onMouseDown={onResize}
      onTouchStart={onResize}
      onDoubleClick={(event) => {
        const container = event.currentTarget.closest<HTMLElement>(
          "[data-slot=data-table]"
        )
        if (container) {
          setWidth(measureColumnWidths(container, [column])[column.id]!)
        }
      }}
      onKeyDown={(event) => {
        // The arrow pointing away from the column widens it, whichever the direction.
        const step = (event.shiftKey ? LARGE_STEP : STEP) * direction
        if (event.key === "ArrowRight") setWidth(size + step)
        else if (event.key === "ArrowLeft") setWidth(size - step)
        else return
        event.preventDefault()
      }}
      // With `columnResizeMode: "onEnd"` the size lands on release; the line previews it.
      style={preview ? { transform: `translateX(${preview}px)` } : undefined}
      className={cn(
        "absolute inset-y-0 -end-1 z-10 w-2 cursor-col-resize touch-none outline-none select-none",
        "after:absolute after:inset-y-1.5 after:start-1/2 after:w-px after:-translate-x-1/2 after:bg-border after:opacity-0 after:transition-opacity hover:after:opacity-100 focus-visible:after:w-0.5 focus-visible:after:bg-ring focus-visible:after:opacity-100"
      )}
    >
      {isResizing && <ColumnGuideLine className="start-1/2 -translate-x-1/2" />}
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * A vertical line from a header cell down through the rows in view: where a
 * resized column's edge or a moved column will land. Place it in a positioned
 * header cell and set its inline position with `className`.
 */
export function ColumnGuideLine({ className }: { className?: string }) {
  const ref = React.useRef<HTMLSpanElement>(null)
  React.useLayoutEffect(() => {
    const line = ref.current
    const table = line?.closest("table")
    const container = line?.closest("[data-slot=data-table]")
    if (!line || !table || !container) return
    // Down to the last row, or the bottom of the scroll area when it's taller.
    const bottom = Math.min(
      table.getBoundingClientRect().bottom,
      container.getBoundingClientRect().bottom
    )
    line.style.height = `${bottom - line.getBoundingClientRect().top}px`
  }, [])
  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="data-table-guide-line"
      className={cn(
        "pointer-events-none absolute top-0 z-10 h-full w-0.5 bg-primary",
        className
      )}
    />
  )
}

interface LabelledColumn {
  id: string
  columnDef: { header?: unknown; meta?: { label?: string } }
}

/** `meta.label`, else a string `header`, else the column id. */
export function getColumnLabel(column: LabelledColumn): string {
  return (
    column.columnDef.meta?.label ??
    (typeof column.columnDef.header === "string"
      ? column.columnDef.header
      : column.id)
  )
}

// Opaque, so scrolled cells don't show through; the row's hover and selection
// colors are mixed in. Edge columns fade a shadow over the cells scrolled under them.
// Any cell tints with its column's `--column-color` (none when it isn't set).
export const pinnedCellClassName = [
  // A column being moved stands out from the ones it passes.
  "data-dragging:bg-muted!",
  "bg-[linear-gradient(color-mix(in_oklab,var(--column-color)_14%,transparent),color-mix(in_oklab,var(--column-color)_14%,transparent))]",
  "data-pinned:z-10 data-pinned:bg-background group-hover/row:data-pinned:bg-[color-mix(in_oklab,var(--color-muted)_50%,var(--color-background))] group-data-[state=selected]/row:data-pinned:bg-muted",
  "before:pointer-events-none before:absolute before:inset-y-0 before:w-3 before:from-foreground/10 before:to-transparent before:opacity-0 before:transition-opacity",
  "data-[pinned-edge=start]:before:-end-3 data-[pinned-edge=start]:before:bg-linear-to-r group-data-[scroll-start]/data-table:data-[pinned-edge=start]:before:opacity-100 rtl:data-[pinned-edge=start]:before:bg-linear-to-l",
  "data-[pinned-edge=end]:before:-start-3 data-[pinned-edge=end]:before:bg-linear-to-l group-data-[scroll-end]/data-table:data-[pinned-edge=end]:before:opacity-100 rtl:data-[pinned-edge=end]:before:bg-linear-to-r",
].join(" ")

// A sticky header loses its row border to border-collapse, so each cell draws one.
export const headerCellClassName =
  "relative bg-background after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:bg-border"

import type { CSSProperties } from "react"

import { columnColorStyle } from "@/registry/shared/table/column-color-palette"

interface PinnableColumn {
  id: string
  getIsPinned: () => false | "start" | "end"
  getStart: (position?: "start" | "end" | "center") => number
  getAfter: (position?: "start" | "end" | "center") => number
  getSize: () => number
  getColor: () => string | undefined
}

interface PinnableTable {
  getStartVisibleLeafColumns: () => { id: string }[]
  getEndVisibleLeafColumns: () => { id: string }[]
}

/** The pinned columns next to the scrolling ones, which cast the scroll shadow. */
export interface PinnedEdges {
  start?: string
  end?: string
}

export function getPinnedEdges(table: PinnableTable): PinnedEdges {
  return {
    start: table.getStartVisibleLeafColumns().at(-1)?.id,
    end: table.getEndVisibleLeafColumns()[0]?.id,
  }
}

/**
 * Width and color, plus `position: sticky` at TanStack's offsets for pinned
 * columns. Logical insets, so pinning follows the reading direction.
 */
export function getColumnCellProps(column: PinnableColumn, edges: PinnedEdges) {
  const pinned = column.getIsPinned()
  const style: CSSProperties = {
    width: column.getSize(),
    ...columnColorStyle(column.getColor()),
  }
  if (pinned === "start") {
    style.position = "sticky"
    style.insetInlineStart = column.getStart("start")
  } else if (pinned === "end") {
    style.position = "sticky"
    style.insetInlineEnd = column.getAfter("end")
  }
  return {
    "data-column-id": column.id,
    "data-pinned": pinned || undefined,
    "data-pinned-edge":
      column.id === edges.start
        ? "start"
        : column.id === edges.end
          ? "end"
          : undefined,
    style,
  }
}

interface PinnableHeader {
  isPlaceholder: boolean
  subHeaders: unknown[]
  column: PinnableColumn
  getSize: () => number
  getLeafHeaders: () => { column: PinnableColumn; subHeaders: unknown[] }[]
}

/**
 * Like `getColumnCellProps`, for header cells: a placeholder follows its leaf
 * column, and a group sticks when all its columns are pinned to one side.
 */
export function getHeaderCellProps(header: PinnableHeader, edges: PinnedEdges) {
  if (header.isPlaceholder || header.subHeaders.length === 0) {
    return getColumnCellProps(header.column, edges)
  }
  const leaves = header
    .getLeafHeaders()
    .filter((leaf) => leaf.subHeaders.length === 0)
    .map((leaf) => leaf.column)
  const sides = new Set(leaves.map((column) => column.getIsPinned()))
  const pinned = sides.size === 1 ? [...sides][0]! : false
  const first = leaves[0]
  const last = leaves.at(-1)
  const style: CSSProperties = { width: header.getSize() }
  if (pinned === "start" && first) {
    style.position = "sticky"
    style.insetInlineStart = first.getStart("start")
  } else if (pinned === "end" && last) {
    style.position = "sticky"
    style.insetInlineEnd = last.getAfter("end")
  }
  return {
    "data-pinned": pinned || undefined,
    "data-pinned-edge":
      pinned === "start" && last?.id === edges.start
        ? "start"
        : pinned === "end" && first?.id === edges.end
          ? "end"
          : undefined,
    style,
  }
}

import { useEffect, useRef, useState } from "react"

export interface ScrollEdges {
  /** Content is scrolled out of view at the start. */
  start: boolean
  /** More content waits past the end. */
  end: boolean
}

/** Tracks horizontal overflow on both sides of a scroll container. */
export function useScrollEdges<T extends HTMLElement>() {
  const ref = useRef<T>(null)
  const [edges, setEdges] = useState<ScrollEdges>({ start: false, end: false })

  useEffect(() => {
    const node = ref.current
    if (!node) return
    const update = () => {
      // Negative in right-to-left layouts.
      const scrolled = Math.abs(node.scrollLeft)
      const start = scrolled > 0
      const end = scrolled + node.clientWidth < node.scrollWidth - 1
      setEdges((previous) =>
        previous.start === start && previous.end === end
          ? previous
          : { start, end }
      )
    }
    update()
    node.addEventListener("scroll", update, { passive: true })
    const observer = new ResizeObserver(update)
    observer.observe(node)
    if (node.firstElementChild) observer.observe(node.firstElementChild)
    return () => {
      node.removeEventListener("scroll", update)
      observer.disconnect()
    }
  }, [])

  return [ref, edges] as const
}

import type { DataTableInstance } from "@querycn/table-react"

/** Selected rows on the page; a selected row pushed to another page doesn't count. */
export function getSelectedPageRows<TData extends object>(
  table: DataTableInstance<TData>
) {
  return table.getRowModel().rows.filter((row) => row.getIsSelected())
}

/** What the pagination bar shows, read from the table. */
export function getPaginationState<TData extends object>(
  table: DataTableInstance<TData>
) {
  const { pageIndex, pageSize } = table.store.state.pagination
  const pageRows = table.getRowModel().rows
  // Server mode before the backend's first total.
  const isTotalUnknown =
    table.options.manualPagination && table.options.rowCount === undefined
  // A first page that isn't full is every row there is.
  const rowCount =
    !isTotalUnknown || (pageIndex === 0 && pageRows.length < pageSize)
      ? table.getRowCount()
      : undefined
  const pageCount = rowCount === undefined ? undefined : table.getPageCount()
  // The URL only accepts these; the current size is there even if it's another.
  const pageSizes = [
    ...new Set([...(table.options.meta?.pageSizes ?? []), pageSize]),
  ].sort((a, b) => a - b)
  // Without a total, a full page is the only hint that another one follows.
  const hasNext =
    pageCount === undefined
      ? pageRows.length >= pageSize
      : pageIndex + 1 < pageCount

  return {
    page: pageIndex + 1,
    pageCount,
    pageSize,
    pageSizes,
    rowCount,
    pageRowCount: pageRows.length,
    selectedCount: getSelectedPageRows(table).length,
    isEmpty: rowCount === 0,
    // Every size would show every row: nothing to pick.
    showPageSizes: rowCount === undefined || rowCount > pageSizes[0]!,
    showPages: pageIndex > 0 || hasNext,
    hasPrevious: pageIndex > 0,
    hasNext,
  }
}

import * as React from "react"

/**
 * Moving to the first or last page disables the button that did it, and the
 * browser drops its focus to `<body>`. This keeps keyboard users in the
 * pagination: focus goes to the current page's button, else the nav itself.
 */
export function useKeepFocusInPagination(page: number) {
  const navRef = React.useRef<HTMLElement>(null)
  // Some browsers blur the disabled button before effects run.
  const hadFocus = React.useRef(false)

  React.useEffect(() => {
    const nav = navRef.current
    if (!nav || !hadFocus.current) return
    const active = document.activeElement
    const lost =
      active === null ||
      active === document.body ||
      (nav.contains(active) && active.matches(":disabled"))
    if (!lost) return
    nav.querySelector<HTMLElement>('[aria-current="page"]')?.focus()
    if (!nav.contains(document.activeElement)) nav.focus()
  }, [page])

  return {
    ref: navRef,
    tabIndex: -1,
    onFocus: () => {
      hadFocus.current = true
    },
    onBlur: (event: React.FocusEvent) => {
      if (
        event.relatedTarget &&
        !event.currentTarget.contains(event.relatedTarget)
      ) {
        hadFocus.current = false
      }
    },
  }
}

import * as React from "react"
import type { DataTableInstance } from "@querycn/table-react"

import { measureColumnWidth } from "@/registry/shared/table/measure-column-width"

type Column<TData extends object> = ReturnType<
  DataTableInstance<TData>["getAllLeafColumns"]
>[number]

const FIT_MAX = 800

/** The width a column may take: its `minSize` and `maxSize`. */
export function getColumnWidthBounds(column: {
  columnDef: { minSize?: number; maxSize?: number }
}) {
  return {
    min: column.columnDef.minSize ?? 20,
    max: column.columnDef.maxSize ?? Number.MAX_SAFE_INTEGER,
  }
}

/** Widths that show each column's rendered cells in full, within its bounds. */
export function measureColumnWidths<TData extends object>(
  container: HTMLElement,
  columns: Column<TData>[]
) {
  return Object.fromEntries(
    columns.map((column) => {
      const { min, max } = getColumnWidthBounds(column)
      return [
        column.id,
        measureColumnWidth(container, column.id, {
          min,
          max: Math.min(max, FIT_MAX),
        }),
      ]
    })
  )
}

// Each table's scroll container, for menus rendered outside it.
const containers = new WeakMap<object, HTMLElement>()

/** `DataTable` registers its scroll container, so menus outside it can measure cells. */
export function useTableContainer(
  table: object,
  ref: React.RefObject<HTMLElement | null>
) {
  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    containers.set(table, node)
    return () => {
      if (containers.get(table) === node) containers.delete(table)
    }
  }, [table, ref])
}

/** Fits the columns (every visible resizable one by default) to their content. */
export function fitColumns<TData extends object>(
  table: DataTableInstance<TData>,
  columns = table.getVisibleLeafColumns().filter((c) => c.getCanResize())
) {
  const container = containers.get(table)
  if (!container || columns.length === 0) return
  const widths = measureColumnWidths(container, columns)
  table.setColumnSizing((sizes) => ({ ...sizes, ...widths }))
}

/**
 * Pins next to the scrolling columns, so columns pinned for good (a selection
 * column) keep the outer edge. `false` unpins.
 */
export function pinColumn<TData extends object>(
  table: DataTableInstance<TData>,
  column: Column<TData>,
  position: "start" | "end" | false
) {
  table.setColumnPinning(({ start = [], end = [] }) => {
    const pinning = {
      start: start.filter((id) => id !== column.id),
      end: end.filter((id) => id !== column.id),
    }
    if (position === "start") pinning.start.push(column.id)
    if (position === "end") pinning.end.unshift(column.id)
    return pinning
  })
}

/**
 * Back to the columns' defaults (order, visibility, pinning, widths, colors),
 * forgetting the saved layout so later column changes apply.
 */
export function resetLayout<TData extends object>(
  table: DataTableInstance<TData>
) {
  table.options.meta?.resetLayout()
}

/**
 * Whether a header gets the ⋯ menu: it has something to sort, pin, fit or
 * hide. A selection column doesn't, and in its narrow cell the ⋯ button
 * would cover the select-all checkbox.
 */
export function hasColumnMenu(column: {
  getCanSort: () => boolean
  getCanPin: () => boolean
  getCanResize: () => boolean
  getCanHide: () => boolean
}) {
  return (
    column.getCanSort() ||
    column.getCanPin() ||
    column.getCanResize() ||
    column.getCanHide()
  )
}

/**
 * The columns a column list shows: every leaf, hidden ones too, in the order
 * the table shows them. Leaves out columns nothing can be done with, such as
 * a selection column.
 */
export function getListedColumns<TData extends object>(
  table: DataTableInstance<TData>
) {
  return [
    ...table.getStartLeafColumns(),
    ...table.getCenterLeafColumns(),
    ...table.getEndLeafColumns(),
  ].filter(
    (column) =>
      column.getCanHide() ||
      column.getCanPin() ||
      (table.options.meta?.enableColumnOrdering !== false &&
        column.columnDef.meta?.enableOrdering !== false)
  )
}

import type { CSSProperties } from "react"

/** Preset colors: mid-tone, so a light tint reads on light and dark themes. */
export const COLUMN_COLOR_PRESETS = {
  red: "oklch(0.64 0.21 25)",
  orange: "oklch(0.7 0.18 50)",
  amber: "oklch(0.78 0.16 80)",
  green: "oklch(0.7 0.17 150)",
  teal: "oklch(0.7 0.12 185)",
  blue: "oklch(0.62 0.19 255)",
  violet: "oklch(0.6 0.22 295)",
  pink: "oklch(0.68 0.2 350)",
} as const

export type ColumnColorPreset = keyof typeof COLUMN_COLOR_PRESETS

export const columnColorPresets = Object.keys(
  COLUMN_COLOR_PRESETS
) as ColumnColorPreset[]

export const isColumnColorPreset = (
  color: string
): color is ColumnColorPreset => Object.hasOwn(COLUMN_COLOR_PRESETS, color)

// Colors come back from localStorage, so only plain color syntax reaches a style:
// no url(), no way out of the declaration.
const SAFE_COLOR =
  /^(#[\da-f]{3,8}|[a-z]+|(rgba?|hsla?|hwb|lab|lch|oklab|oklch)\([\d\s.,%/+-]+\))$/i

/** The CSS color for a stored column color: a preset name or a CSS color. */
export function resolveColumnColor(color: string | undefined) {
  if (color === undefined) return undefined
  if (isColumnColorPreset(color)) return COLUMN_COLOR_PRESETS[color]
  return SAFE_COLOR.test(color) ? color : undefined
}

/**
 * Sets `--column-color` on a cell; `pinnedCellClassName` layers a light tint
 * of it over the cell's own background, so pinned cells stay opaque and hover
 * or selection still shows.
 */
export function columnColorStyle(
  color: string | undefined
): CSSProperties | undefined {
  const resolved = resolveColumnColor(color)
  return resolved
    ? ({ "--column-color": resolved } as CSSProperties)
    : undefined
}

import * as React from "react"

interface ColorableColumn {
  getColor: () => string | undefined
  setColor: (color: string | undefined) => void
}

/**
 * A hidden `<input type="color">` for custom column colors. Render
 * `inputProps` outside any popover or menu (the pick must land after they
 * close) and call `open(column)` from a menu item. Commits once the picker
 * closes, not on every move.
 */
export function useColumnColorPicker() {
  const ref = React.useRef<HTMLInputElement>(null)
  const target = React.useRef<ColorableColumn | null>(null)
  React.useEffect(() => {
    const input = ref.current
    if (!input) return
    // React's onChange fires on every move of the picker; "change" on commit.
    const onChange = () => target.current?.setColor(input.value)
    input.addEventListener("change", onChange)
    return () => input.removeEventListener("change", onChange)
  }, [])

  return {
    inputProps: {
      ref,
      type: "color",
      tabIndex: -1,
      "aria-hidden": true,
      className: "sr-only",
    } as const,
    open: (column: ColorableColumn) => {
      const input = ref.current
      if (!input) return
      target.current = column
      // The picker starts from the current color when it's one it can show.
      const color = column.getColor()
      if (color && /^#[\da-f]{6}$/i.test(color)) input.value = color
      input.click()
    },
  }
}

import * as React from "react"

/**
 * For toolbar controls that go away (clear filters, the selection bar): if
 * focus was inside, it moves to the toolbar instead of falling to the page.
 */
export function useFocusToolbarOnUnmount<T extends HTMLElement>() {
  const ref = React.useRef<T>(null)
  React.useLayoutEffect(() => {
    const node = ref.current
    return () => {
      if (!node?.contains(document.activeElement)) return
      node.closest<HTMLElement>("[data-slot=data-table-toolbar]")?.focus()
    }
  }, [])
  return ref
}

import type * as React from "react"

// Controls inside a row (checkbox, link, menu) don't count as a click on it.
const CONTROLS =
  "a, button, input, label, select, textarea, [role=button], [role=checkbox], [role=menuitem]"

export function isFromControl(event: React.MouseEvent) {
  const target = event.target as Element
  // Portalled menus and popovers bubble through React but sit outside the row.
  if (!event.currentTarget.contains(target)) return true
  const control = target.closest(CONTROLS)
  return control !== null && event.currentTarget.contains(control)
}

// The clicks of a double click, or selecting text, aren't a row click.
export const isRowClick = (event: React.MouseEvent) =>
  !isFromControl(event) &&
  event.detail <= 1 &&
  (window.getSelection()?.isCollapsed ?? true)

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

export interface UseVirtualRowsOptions {
  enabled: boolean
  count: number
  /** The row's id at an index, so a measured height follows the row when it moves. */
  getRowId: (index: number) => string
  scrollRef: React.RefObject<HTMLElement | null>
  estimateRowHeight: number
}

/**
 * Renders only the rows in view, plus a few either side. The rows around them
 * become two spacers, so the scrollbar still reflects the whole list. `null`
 * when off.
 */
export function useVirtualRows({
  enabled,
  count,
  getRowId,
  scrollRef,
  estimateRowHeight,
}: UseVirtualRowsOptions) {
  // React Compiler skips this hook, and what it returns is rebuilt every render.
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: enabled ? count : 0,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => estimateRowHeight,
    getItemKey: getRowId,
    overscan: 10,
  })
  if (!enabled) return null
  const items = virtualizer.getVirtualItems()
  return {
    items,
    before: items[0]?.start ?? 0,
    after: virtualizer.getTotalSize() - (items.at(-1)?.end ?? 0),
    /** The row's ref; the row needs `data-index`. */
    measureRow: virtualizer.measureElement,
  }
}

export type VirtualRows = NonNullable<ReturnType<typeof useVirtualRows>>

import * as React from "react"

/** Back to the first row when `key` (sort, page, filter…) changes. */
export function useScrollToTopOnChange(
  ref: React.RefObject<HTMLElement | null>,
  key: string
) {
  const last = React.useRef(key)
  // Before paint, so the new rows never show at the old position.
  React.useLayoutEffect(() => {
    if (last.current === key) return
    last.current = key
    if (ref.current) ref.current.scrollTop = 0
  }, [ref, key])
}

import * as React from "react"
import type { DataTableInstance } from "@querycn/table-react"

/**
 * The search box's text, written to the URL once typing pauses for `delay`
 * ms, or right away on Enter and clear. A search changed elsewhere (back and
 * forward, Clear filters) shows up in the box.
 */
export function useDataTableSearch<TData extends object>(
  table: DataTableInstance<TData>,
  delay: number
) {
  const meta = table.options.meta
  const search = meta?.search ?? ""
  // `meta` is rebuilt every render; the setter keeps its identity, so typing
  // isn't pushed back by unrelated renders.
  const setSearch = meta?.setSearch
  const [value, setValue] = React.useState(search)
  const [shown, setShown] = React.useState(search)
  if (search !== shown) {
    setShown(search)
    // Keeps what's being typed, trailing space included, when it's the same search.
    if (value.trim() !== search) setValue(search)
  }

  const commit = React.useCallback(
    (text: string) => setSearch?.(text),
    [setSearch]
  )
  React.useEffect(() => {
    if (value.trim() === search) return
    const timer = setTimeout(() => commit(value), delay)
    return () => clearTimeout(timer)
  }, [value, search, delay, commit])

  return {
    value,
    setValue,
    clear: () => {
      setValue("")
      commit("")
    },
    commitNow: () => commit(value),
  }
}

export type PageRangeItem = number | "ellipsis-start" | "ellipsis-end"

/**
 * Page buttons to show, 1-based: at most `slots` (7 by default), always with
 * the first and last page, e.g. `1 … 4 5 6 … 20`. Each ellipsis has its own
 * key so it can be a React key.
 */
export function pageRange(
  page: number,
  pageCount: number,
  slots = 7
): PageRangeItem[] {
  // First, last, two ellipses and the current page need five.
  slots = Math.max(slots, 5)
  if (pageCount <= slots) {
    return Array.from({ length: pageCount }, (_, i) => i + 1)
  }
  const current = Math.min(
    Math.max(Number.isFinite(page) ? page : 1, 1),
    pageCount
  )
  const middle = slots - 4
  const edge = slots - 2
  let range: PageRangeItem[]
  if (current <= edge - 1) {
    range = [
      ...Array.from({ length: edge }, (_, i) => i + 1),
      "ellipsis-end",
      pageCount,
    ]
  } else if (current >= pageCount - edge + 2) {
    range = [
      1,
      "ellipsis-start",
      ...Array.from({ length: edge }, (_, i) => pageCount - edge + 1 + i),
    ]
  } else {
    const start = current - Math.floor((middle - 1) / 2)
    range = [
      1,
      "ellipsis-start",
      ...Array.from({ length: middle }, (_, i) => start + i),
      "ellipsis-end",
      pageCount,
    ]
  }
  // An ellipsis standing for a single page shows that page instead.
  return range.map((item, i) =>
    item === "ellipsis-start" && range[i + 1] === 3
      ? 2
      : item === "ellipsis-end" && range[i - 1] === pageCount - 2
        ? pageCount - 1
        : item
  )
}

export interface MeasureColumnWidthOptions {
  min?: number
  max?: number
}

/**
 * The width a column needs to show every rendered header and cell in full:
 * the cells marked `data-column-id` inside `container`. A cell's first child
 * element is its content; it is laid out at `max-content` for the reading and
 * put back. Cells holding only text are measured by their text, so keep them
 * on one line (`whitespace-nowrap`).
 */
export function measureColumnWidth(
  container: HTMLElement,
  columnId: string,
  { min = 40, max = 800 }: MeasureColumnWidthOptions = {}
): number {
  const cells = [
    ...container.querySelectorAll<HTMLElement>(
      `[data-column-id="${CSS.escape(columnId)}"]`
    ),
  ]
  const contents = cells.map((cell) =>
    cell.firstElementChild instanceof HTMLElement
      ? cell.firstElementChild
      : null
  )
  // Write all, read all, restore all: one layout for the whole column, not one per cell.
  const previous = contents.map((content) => content?.style.width ?? "")
  for (const content of contents) {
    if (content) content.style.width = "max-content"
  }
  let width = 0
  cells.forEach((cell, i) => {
    const style = getComputedStyle(cell)
    const padding =
      (parseFloat(style.paddingLeft) || 0) +
      (parseFloat(style.paddingRight) || 0)
    width = Math.max(width, contentWidth(cell, contents[i]!) + padding)
  })
  contents.forEach((content, i) => {
    if (content) content.style.width = previous[i]!
  })
  return Math.min(Math.max(Math.ceil(width), min), max)
}

function contentWidth(cell: HTMLElement, content: HTMLElement | null) {
  if (content) return content.getBoundingClientRect().width
  const range = document.createRange()
  range.selectNodeContents(cell)
  return range.getBoundingClientRect().width
}
